highp vec3 scratch3_convertHue2RGB(highp float hue)
{
	highp float r = abs(hue * 6.0 - 3.0) - 1.0;
	highp float g = 2.0 - abs(hue * 6.0 - 2.0);
	highp float b = 2.0 - abs(hue * 6.0 - 4.0);
	return clamp(vec3(r, g, b), 0.0, 1.0);
